    // the sections a setting needs to be heard
    static void prep(string t, Fx g)
    {
        if (t == "pxcurve") { for (int k = 0; k < 8; k++) g.Set("b" + k + "_on", 1); }
        if (t == "pxref") { var rl = new float[SR * 3]; for (int i = 0; i < rl.Length; i++) rl[i] = (float)(0.3 * Math.Sin(2 * Math.PI * 110 * i / SR) + 0.2 * Math.Sin(2 * Math.PI * 2500 * i / SR) + 0.1 * Math.Sin(2 * Math.PI * 7000 * i / SR)); var rr = (float[])rl.Clone(); for (int i = 0; i < rr.Length; i++) rr[i] *= 0.6f; ((ReferenceFx)g).SetReference(rl, rr, "test"); }
        if (t == "pxmorph") { var m = new float[SR]; for (int i = 0; i < m.Length; i++) m[i] = (float)(0.3 * Math.Sin(2 * Math.PI * 800 * i / SR) * (0.5 + 0.5 * Math.Sin(2 * Math.PI * 3 * i / SR))); ((MorphFx)g).TestMod = m; }
    }
    static void needs(string t, string id, Fx g)
    {
        if (t == "pxcurrent") { if (id == "b_det" || id == "b_spr") g.Set("b_uni", 3); if (id == "a2" || id == "d2" || id == "s2" || id == "r2") { g.Set("m0_amt", 80); if (id == "r2") g.Set("s2", 100); } if (id == "lrate" || id == "lshape") g.Set("m1_amt", 80);
                                if (id.Length == 6 && id[0] == 'm' && char.IsDigit(id[1])) { string p = id.Substring(0, 3); if (!id.EndsWith("amt")) g.Set(p + "amt", 80); if (g.Get(p + "src") < 0.5f && !id.EndsWith("src")) g.Set(p + "src", 2); } }
        if (t == "pxinferno") { if (id == "fm") g.Set("wave", 3); }
        if (t == "pxref") { if (id == "trim" || id == "match" || id == "mono") { g.Set("listen", 1); if (id == "trim") g.Set("match", 0); } }
        if (t == "pxmorph") { if (id == "sens") g.Set("mode", 2); if (id == "smooth" || id == "formant") g.Set("mode", 1); if (id == "amt") g.Set("mode", 0); }
